'use strict';

/**
 * Thrown by ShoppingCart#removeItem when no line in the cart has the given name.
 * The requested name is kept on `itemName` so callers can report it.
 */
class ItemNotFoundError extends Error {
  /** @param {string} itemName */
  constructor(itemName) {
    super(`No item named ${JSON.stringify(itemName)} is in the cart`);
    this.name = 'ItemNotFoundError';
    this.itemName = itemName;
  }
}

module.exports = { ItemNotFoundError };

