'use strict';

const assert = require('node:assert/strict');

// Totals with fractional prices are floats, so exact equality would fail on
// rounding noise such as 0.1 + 0.2.
const FLOAT_TOLERANCE = 1e-9;

function assertCloseTo(actual, expected, tolerance = FLOAT_TOLERANCE) {
  assert.ok(
    Math.abs(actual - expected) <= tolerance,
    `expected ${actual} to be within ${tolerance} of ${expected}`,
  );
}

// Deep copy of the observable cart state, for asserting that a rejected call
// left the cart exactly as it was.
function snapshot(cart) {
  return structuredClone({ items: cart.items, discount: cart.discount });
}

module.exports = { assertCloseTo, snapshot };

