'use strict';

const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');

const ShoppingCart = require('../src/cart');
const { ItemNotFoundError } = require('../src/errors');
const { assertCloseTo, snapshot } = require('./helpers');

const NON_NUMBERS = [
  ['NaN', NaN],
  ['Infinity', Infinity],
  ['-Infinity', -Infinity],
  ['a numeric string', '5'],
  ['null', null],
  ['undefined', undefined],
  ['a boxed Number', Object(5)],
];

describe('ShoppingCart', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('regressions for the five original bugs', () => {
    it('bug 1: addItem rejects a negative price instead of storing it', () => {
      assert.throws(() => cart.addItem('apple', -1, 1), RangeError);
      assert.deepEqual(cart.items, []);
    });

    it('bug 1: addItem rejects a negative quantity instead of storing it', () => {
      assert.throws(() => cart.addItem('apple', 1, -2), RangeError);
      assert.deepEqual(cart.items, []);
    });

    it('bug 1: a negative quantity cannot shrink an existing line', () => {
      cart.addItem('apple', 1, 3);
      assert.throws(() => cart.addItem('apple', 1, -2), RangeError);
      assert.equal(cart.items[0].quantity, 3);
    });

    it('bug 2: removeItem keeps the other items and does not rename them via =', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);
      cart.addItem('cherry', 3, 1);

      cart.removeItem('banana');

      assert.deepEqual(cart.items, [
        { name: 'apple', price: 1, quantity: 1 },
        { name: 'cherry', price: 3, quantity: 1 },
      ]);
    });

    it('bug 2: removeItem throws ItemNotFoundError for a missing item', () => {
      cart.addItem('apple', 1, 1);
      const before = snapshot(cart);

      assert.throws(() => cart.removeItem('pear'), ItemNotFoundError);
      assert.deepEqual(snapshot(cart), before);
    });

    it('bug 3: getTotal stops at the last item instead of reading items[length]', () => {
      cart.addItem('apple', 2, 3);
      cart.addItem('banana', 5, 1);
      assert.equal(cart.getTotal(), 11);
    });

    it('bug 3: getTotal of an empty cart is 0 instead of a TypeError', () => {
      assert.equal(cart.getTotal(), 0);
    });

    it('bug 4: getTotal subtracts the discount instead of adding it', () => {
      cart.addItem('jacket', 200, 1);
      cart.applyDiscount(10);
      assert.equal(cart.getTotal(), 180);
    });

    it('bug 5: applyDiscount rejects a percentage above 100', () => {
      assert.throws(() => cart.applyDiscount(150), RangeError);
      assert.equal(cart.discount, 0);
    });

    it('bug 5: applyDiscount rejects a negative percentage', () => {
      assert.throws(() => cart.applyDiscount(-5), RangeError);
      assert.equal(cart.discount, 0);
    });
  });

  describe('addItem', () => {
    it('adds a new line with the given name, price and quantity', () => {
      cart.addItem('apple', 1.5, 2);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 2 }]);
    });

    it('adds different names as separate lines in insertion order', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);
      assert.deepEqual(cart.items.map(i => i.name), ['apple', 'banana']);
    });

    it('merges the quantity into an existing line with the same name', () => {
      cart.addItem('apple', 1, 2);
      cart.addItem('apple', 1, 3);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1, quantity: 5 }]);
    });

    it('keeps the first price when the same name is added again at another price', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('apple', 9, 1);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1, quantity: 2 }]);
    });

    it('accepts a price of zero for free items', () => {
      cart.addItem('sticker', 0, 4);
      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.getTotal(), 0);
    });

    it('rejects a quantity of zero', () => {
      assert.throws(() => cart.addItem('apple', 1, 0), RangeError);
      assert.deepEqual(cart.items, []);
    });

    it('rejects a fractional quantity', () => {
      assert.throws(() => cart.addItem('apple', 1, 1.5), RangeError);
      assert.deepEqual(cart.items, []);
    });

    for (const [label, value] of NON_NUMBERS) {
      it(`rejects ${label} as a price with a TypeError`, () => {
        assert.throws(() => cart.addItem('apple', value, 1), TypeError);
        assert.deepEqual(cart.items, []);
      });

      it(`rejects ${label} as a quantity with a TypeError`, () => {
        assert.throws(() => cart.addItem('apple', 1, value), TypeError);
        assert.deepEqual(cart.items, []);
      });
    }

    for (const [label, value] of [
      ['an empty name', ''],
      ['a whitespace-only name', '  \t\n'],
      ['a numeric name', 42],
      ['a missing name', undefined],
    ]) {
      it(`rejects ${label} with a TypeError`, () => {
        assert.throws(() => cart.addItem(value, 1, 1), TypeError);
        assert.deepEqual(cart.items, []);
      });
    }

    it('names the bad argument and the received value in the error message', () => {
      assert.throws(() => cart.addItem('apple', -3, 1), {
        name: 'RangeError',
        message: /price.*-3/,
      });
      assert.throws(() => cart.addItem('apple', 1, '2'), {
        name: 'TypeError',
        message: /quantity.*"2"/,
      });
    });
  });

  describe('removeItem', () => {
    it('removes the whole line whatever its quantity', () => {
      cart.addItem('apple', 1, 7);
      cart.removeItem('apple');
      assert.deepEqual(cart.items, []);
      assert.equal(cart.getItemCount(), 0);
    });

    it('lowers the total by the removed line', () => {
      cart.addItem('apple', 2, 2);
      cart.addItem('banana', 3, 1);
      cart.removeItem('apple');
      assert.equal(cart.getTotal(), 3);
    });

    it('throws ItemNotFoundError when the cart is empty', () => {
      assert.throws(() => cart.removeItem('apple'), ItemNotFoundError);
    });

    it('throws ItemNotFoundError when the same item is removed twice', () => {
      cart.addItem('apple', 1, 1);
      cart.removeItem('apple');
      assert.throws(() => cart.removeItem('apple'), ItemNotFoundError);
    });

    it('reports the missing name on the error', () => {
      assert.throws(() => cart.removeItem('pear'), error => {
        assert.ok(error instanceof ItemNotFoundError);
        assert.equal(error.itemName, 'pear');
        assert.match(error.message, /"pear"/);
        return true;
      });
    });

    it('matches names exactly, so a different case is not found', () => {
      cart.addItem('Apple', 1, 1);
      assert.throws(() => cart.removeItem('apple'), ItemNotFoundError);
      assert.equal(cart.getItemCount(), 1);
    });

    it('rejects a non-string name with a TypeError', () => {
      cart.addItem('apple', 1, 1);
      assert.throws(() => cart.removeItem(null), TypeError);
      assert.equal(cart.getItemCount(), 1);
    });
  });

  describe('getTotal', () => {
    it('returns price × quantity for a single line', () => {
      cart.addItem('apple', 4, 3);
      assert.equal(cart.getTotal(), 12);
    });

    it('sums fractional prices within floating-point tolerance', () => {
      cart.addItem('gum', 0.1, 1);
      cart.addItem('mint', 0.2, 1);
      assertCloseTo(cart.getTotal(), 0.3);
    });

    it('returns the undiscounted subtotal when no discount is applied', () => {
      cart.addItem('apple', 10, 2);
      assert.equal(cart.getTotal(), 20);
    });

    it('returns the full subtotal with a 0% discount', () => {
      cart.addItem('apple', 10, 2);
      cart.applyDiscount(0);
      assert.equal(cart.getTotal(), 20);
    });

    it('returns 0 with a 100% discount', () => {
      cart.addItem('apple', 10, 2);
      cart.applyDiscount(100);
      assert.equal(cart.getTotal(), 0);
    });

    it('applies a fractional discount percentage', () => {
      cart.addItem('apple', 80, 1);
      cart.applyDiscount(12.5);
      assert.equal(cart.getTotal(), 70);
    });

    it('applies the discount to items added after it was set', () => {
      cart.applyDiscount(50);
      cart.addItem('apple', 10, 1);
      cart.addItem('banana', 30, 1);
      assert.equal(cart.getTotal(), 20);
    });

    it('returns 0 for a discounted empty cart', () => {
      cart.applyDiscount(25);
      assert.equal(cart.getTotal(), 0);
    });

    it('does not change cart state', () => {
      cart.addItem('apple', 3, 2);
      cart.applyDiscount(10);
      const before = snapshot(cart);
      cart.getTotal();
      cart.getTotal();
      assert.deepEqual(snapshot(cart), before);
    });
  });

  describe('applyDiscount', () => {
    it('accepts the 0 and 100 boundaries', () => {
      cart.applyDiscount(0);
      assert.equal(cart.discount, 0);
      cart.applyDiscount(100);
      assert.equal(cart.discount, 100);
    });

    it('rejects values just outside the 0 to 100 range', () => {
      assert.throws(() => cart.applyDiscount(100.0001), RangeError);
      assert.throws(() => cart.applyDiscount(-0.0001), RangeError);
      assert.equal(cart.discount, 0);
    });

    it('replaces the previous discount rather than stacking with it', () => {
      cart.addItem('apple', 100, 1);
      cart.applyDiscount(10);
      cart.applyDiscount(20);
      assert.equal(cart.getTotal(), 80);
    });

    it('keeps the previous discount when a new one is rejected', () => {
      cart.addItem('apple', 100, 1);
      cart.applyDiscount(10);
      assert.throws(() => cart.applyDiscount(101), RangeError);
      assert.equal(cart.discount, 10);
      assert.equal(cart.getTotal(), 90);
    });

    for (const [label, value] of NON_NUMBERS) {
      it(`rejects ${label} with a TypeError`, () => {
        assert.throws(() => cart.applyDiscount(value), TypeError);
        assert.equal(cart.discount, 0);
      });
    }

    it('says what range is allowed in the error message', () => {
      assert.throws(() => cart.applyDiscount(150), {
        message: /between 0 and 100.*150/,
      });
    });
  });

  describe('getItemCount', () => {
    it('returns 0 for a new cart', () => {
      assert.equal(cart.getItemCount(), 0);
    });

    it('counts distinct lines, not units', () => {
      cart.addItem('apple', 1, 5);
      cart.addItem('banana', 1, 2);
      cart.addItem('apple', 1, 1);
      assert.equal(cart.getItemCount(), 2);
    });

    it('drops by one after a removal', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 1, 1);
      cart.removeItem('apple');
      assert.equal(cart.getItemCount(), 1);
    });

    it('is unchanged by a rejected addItem', () => {
      cart.addItem('apple', 1, 1);
      assert.throws(() => cart.addItem('banana', -1, 1), RangeError);
      assert.equal(cart.getItemCount(), 1);
    });
  });
});

