'use strict';

// Each assertion throws TypeError for a value of the wrong kind and RangeError
// for a value of the right kind outside the allowed range. They return nothing,
// so callers can check every argument before touching any state.

function formatReceived(value) {
  if (typeof value === 'string') return JSON.stringify(value);
  if (typeof value === 'bigint') return `${value}n`;
  if (value !== null && (typeof value === 'object' || typeof value === 'function')) {
    return Object.prototype.toString.call(value);
  }
  // String() rather than a template literal: interpolating a Symbol throws.
  return String(value);
}

/**
 * @param {unknown} value
 * @param {string} label argument name used in the error message
 * @throws {TypeError} unless value is a string with at least one non-whitespace character
 */
function assertNonEmptyString(value, label) {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new TypeError(`${label} must be a non-empty string, received ${formatReceived(value)}`);
  }
}

/**
 * Rejects NaN, ±Infinity, numeric strings and boxed Numbers.
 * @param {unknown} value
 * @param {string} label
 * @throws {TypeError}
 */
function assertFiniteNumber(value, label) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`${label} must be a finite number, received ${formatReceived(value)}`);
  }
}

/**
 * @param {unknown} value
 * @param {string} label
 * @throws {TypeError|RangeError}
 */
function assertNonNegativeNumber(value, label) {
  assertFiniteNumber(value, label);
  if (value < 0) {
    throw new RangeError(`${label} must be 0 or greater, received ${value}`);
  }
}

/**
 * Accepts 1 through Number.MAX_SAFE_INTEGER. Larger integers lose precision
 * under addition, which would corrupt merged quantities.
 * @param {unknown} value
 * @param {string} label
 * @throws {TypeError|RangeError}
 */
function assertPositiveSafeInteger(value, label) {
  assertFiniteNumber(value, label);
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new RangeError(
      `${label} must be a whole number from 1 to ${Number.MAX_SAFE_INTEGER}, received ${value}`,
    );
  }
}

/**
 * @param {unknown} value
 * @param {string} label
 * @param {number} min inclusive
 * @param {number} max inclusive
 * @throws {TypeError|RangeError}
 */
function assertNumberInRange(value, label, min, max) {
  assertFiniteNumber(value, label);
  if (value < min || value > max) {
    throw new RangeError(`${label} must be between ${min} and ${max} inclusive, received ${value}`);
  }
}

module.exports = {
  assertNonEmptyString,
  assertFiniteNumber,
  assertNonNegativeNumber,
  assertPositiveSafeInteger,
  assertNumberInRange,
};

