   * Adds a line, or adds to the quantity of the line that already has this
   * name. An existing line keeps the price it was first added with.
   * @param {string} name matched exactly, including case
   * @param {number} price unit price, 0 or greater (0 for free items)
   * @param {number} quantity whole number, 1 or greater
   * @throws {TypeError|RangeError}
   */
  addItem(name, price, quantity) {
    assertNonEmptyString(name, 'name');
    assertNonNegativeNumber(price, 'price');
    assertPositiveSafeInteger(quantity, 'quantity');

