  applyDiscount(percent) {
    assertNumberInRange(percent, 'discount percent', MIN_DISCOUNT_PERCENT, MAX_DISCOUNT_PERCENT);
    this.discount = percent;
  }

  /**
   * @returns {number} number of distinct lines, not the sum of their quantities
   */
  getItemCount() {
    return this.items.length;
  }
}

