'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');

const {
  assertNonEmptyString,
  assertFiniteNumber,
  assertNonNegativeNumber,
  assertPositiveSafeInteger,
  assertNumberInRange,
} = require('../src/validation');

describe('assertNonEmptyString', () => {
  for (const value of ['a', ' padded ', 'café', '🍎', 'x'.repeat(5000)]) {
    it(`accepts ${JSON.stringify(value.slice(0, 12))}`, () => {
      assert.doesNotThrow(() => assertNonEmptyString(value, 'name'));
    });
  }

  for (const [label, value] of [
    ['an empty string', ''],
    ['whitespace only', ' \t\n '],
    ['a number', 7],
    ['null', null],
    ['an array', ['a']],
    ['a String object', Object('a')],
  ]) {
    it(`rejects ${label} with a TypeError`, () => {
      assert.throws(() => assertNonEmptyString(value, 'name'), TypeError);
    });
  }

  it('uses the label in the message', () => {
    assert.throws(() => assertNonEmptyString('', 'title'), { message: /^title must be/ });
  });
});

describe('assertFiniteNumber', () => {
  for (const value of [0, -0, -12.5, Number.MIN_VALUE, Number.MAX_VALUE]) {
    it(`accepts ${value}`, () => {
      assert.doesNotThrow(() => assertFiniteNumber(value, 'n'));
    });
  }

  for (const [label, value] of [
    ['NaN', NaN],
    ['Infinity', Infinity],
    ['a numeric string', '1'],
    ['a bigint', 1n],
    ['a symbol', Symbol('one')],
    ['a function', () => 1],
  ]) {
    it(`rejects ${label} with a TypeError`, () => {
      assert.throws(() => assertFiniteNumber(value, 'n'), TypeError);
    });
  }

  it('describes the received value in the message', () => {
    assert.throws(() => assertFiniteNumber(1n, 'n'), { message: /received 1n$/ });
    assert.throws(() => assertFiniteNumber(Symbol('one'), 'n'), { message: /received Symbol\(one\)$/ });
    assert.throws(() => assertFiniteNumber([], 'n'), { message: /received \[object Array\]$/ });
    assert.throws(() => assertFiniteNumber(null, 'n'), { message: /received null$/ });
  });
});

describe('assertNonNegativeNumber', () => {
  it('accepts 0 and positive numbers', () => {
    assert.doesNotThrow(() => assertNonNegativeNumber(0, 'price'));
    assert.doesNotThrow(() => assertNonNegativeNumber(0.01, 'price'));
  });

  it('rejects the smallest negative number with a RangeError', () => {
    assert.throws(() => assertNonNegativeNumber(-Number.MIN_VALUE, 'price'), RangeError);
  });

  it('rejects a non-number with a TypeError before checking the range', () => {
    assert.throws(() => assertNonNegativeNumber('-1', 'price'), TypeError);
  });
});

describe('assertPositiveSafeInteger', () => {
  it('accepts 1 and Number.MAX_SAFE_INTEGER', () => {
    assert.doesNotThrow(() => assertPositiveSafeInteger(1, 'qty'));
    assert.doesNotThrow(() => assertPositiveSafeInteger(Number.MAX_SAFE_INTEGER, 'qty'));
  });

  for (const value of [0, -1, 0.5, 1.0000001, Number.MAX_SAFE_INTEGER + 1]) {
    it(`rejects ${value} with a RangeError`, () => {
      assert.throws(() => assertPositiveSafeInteger(value, 'qty'), RangeError);
    });
  }

  it('rejects NaN with a TypeError', () => {
    assert.throws(() => assertPositiveSafeInteger(NaN, 'qty'), TypeError);
  });
});

describe('assertNumberInRange', () => {
  it('accepts both inclusive bounds and a value between them', () => {
    for (const value of [0, 50, 100]) {
      assert.doesNotThrow(() => assertNumberInRange(value, 'pct', 0, 100));
    }
  });

  it('respects the bounds it is given', () => {
    assert.doesNotThrow(() => assertNumberInRange(-5, 'offset', -10, -1));
    assert.throws(() => assertNumberInRange(0, 'offset', -10, -1), RangeError);
  });

  it('rejects values past either bound with a RangeError naming the range', () => {
    assert.throws(() => assertNumberInRange(-1, 'pct', 0, 100), {
      name: 'RangeError',
      message: 'pct must be between 0 and 100 inclusive, received -1',
    });
    assert.throws(() => assertNumberInRange(101, 'pct', 0, 100), RangeError);
  });

  it('rejects Infinity with a TypeError even when max is large', () => {
    assert.throws(() => assertNumberInRange(Infinity, 'pct', 0, Number.MAX_VALUE), TypeError);
  });
});

