'use strict';

const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');

const ShoppingCart = require('../src/cart');
const { ItemNotFoundError } = require('../src/errors');
const { assertCloseTo, snapshot } = require('./helpers');

describe('ShoppingCart edge cases', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('instance isolation', () => {
    it('keeps items and discount separate between two carts', () => {
      const other = new ShoppingCart();
      cart.addItem('apple', 10, 1);
      cart.applyDiscount(50);

      assert.deepEqual(other.items, []);
      assert.equal(other.discount, 0);
      assert.equal(other.getTotal(), 0);
      assert.equal(cart.getTotal(), 5);
    });

    it('does not let removal in one cart affect another', () => {
      const other = new ShoppingCart();
      cart.addItem('apple', 1, 1);
      other.addItem('apple', 1, 1);

      cart.removeItem('apple');

      assert.equal(other.getItemCount(), 1);
    });
  });

  describe('names', () => {
    it('adds, merges and removes non-ASCII names', () => {
      cart.addItem('café', 3, 1);
      cart.addItem('🍎', 1, 2);
      cart.addItem('日本茶', 5, 1);
      cart.addItem('🍎', 1, 1);

      assert.equal(cart.getItemCount(), 3);
      assert.equal(cart.items[1].quantity, 3);

      cart.removeItem('café');
