TMP=$(mktemp -d) && cp -R src tests package.json "$TMP"/ && cat > "$TMP/mutate.js" <<'EOF'
const fs = require('node:fs');
const path = require('node:path');
const file = path.join(__dirname, 'src/cart.js');
const fixed = fs.readFileSync(file, 'utf8');
const mutants = {
  '1': [["    assertNonNegativeNumber(price, 'price');\n", ''],
        ["    assertPositiveSafeInteger(quantity, 'quantity');\n", ''],
        ["      assertPositiveSafeInteger(merged, `merged quantity for ${JSON.stringify(name)}`);\n", '']],
  '2a': [['i.name !== name', 'i.name = name']],
  '2b': [['    if (remaining.length === this.items.length) {\n      throw new ItemNotFoundError(name);\n    }\n', '']],
  '3': [['    for (const item of this.items) {\n      subtotal += item.price * item.quantity;\n    }',
         '    for (let i = 0; i <= this.items.length; i++) {\n      subtotal += this.items[i].price * this.items[i].quantity;\n    }']],
  '4': [['return subtotal - (', 'return subtotal + (']],
  '5': [["    assertNumberInRange(percent, 'discount percent', MIN_DISCOUNT_PERCENT, MAX_DISCOUNT_PERCENT);\n", '']],
};
const id = process.argv[2];
if (id === 'restore') { fs.writeFileSync(file, fixed); process.exit(0); }
let src = fixed;
for (const [from, to] of mutants[id]) {
  if (!src.includes(from)) { console.error(`mutant ${id}: target not found: ${from}`); process.exit(2); }
  src = src.replace(from, to);
}
fs.writeFileSync(file, src);
EOF
cp src/cart.js "$TMP/cart.fixed.js"
for m in 1 2a 2b 3 4 5; do
  cp "$TMP/cart.fixed.js" "$TMP/src/cart.js"
  node "$TMP/mutate.js" "$m" || { echo "mutation $m failed to apply"; continue; }
  bug=${m%[ab]}
  out=$(cd "$TMP" && node --test --test-name-pattern="^bug $bug:" tests/cart.test.js 2>&1)
  echo "mutant $m -> $(echo "$out" | grep -E '^ℹ (pass|fail)' | tr '\n' ' ')"
  echo "$out" | grep -E '^✖ bug' | sed 's/ ([0-9.]*ms)//; s/^/    /'
done
rm -rf "$TMP"

